mapper.select:
/* PodMapper.selectPodList : POD(쿠팡) List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT * FROM ( SELECT od.OD_JOB_NO ,MAX(od.MASTER_OD_JOB_NO) AS MASTER_OD_JOB_NO ,od.ENT_CODE ,od.ENT_BUSINESS_CODE ,od.BOUND ,od.BOUND_TYPE ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS CUST_NAME_LV2 ,od.PO_NO ,od.PO_DATE ,od.AR_DATE ,od.HBL_NO ,od.DELIVERY_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = od.DELIVERY_CODE) AS DELIVERY_NAME ,od.CD_TYPE ,odAdd.DROP_YN ,odAdd.RETURN_REQUEST_ID ,odAdd.RETURN_REQ_DATE ,MAX(CASE WHEN p03.POD_STATUS = 'ECM065' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_ID_ERROR ,MAX(CASE WHEN ct.POD_STATUS = 'ECM065' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_CUSTOMS_ID_ERROR ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM250' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN od.CD_TYPE = 'Y' AND p03.POD_STATUS = 'ECM210' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_START ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM280' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN od.CD_TYPE = 'Y' AND p03.POD_STATUS = 'ECM240' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_CLEAR ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND ct.POD_STATUS = 'ECM250' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN od.CD_TYPE = 'Y' AND ct.POD_STATUS = 'ECM210' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_CUSTOMS_START ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND ct.POD_STATUS = 'ECM280' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN od.CD_TYPE = 'Y' AND ct.POD_STATUS = 'ECM240' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_CUSTOMS_CLEAR ,MAX(CASE WHEN p04.POD_STATUS = 'ECM361' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM361 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM370' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM370 ,MIN(CASE WHEN p04.POD_STATUS = 'ECM380' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM380 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM390' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM390 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM420' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM420 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM510' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM510 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM520' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM520 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM530' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM530 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM540' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM540 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM550' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM550 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM361' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM361 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM370' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM370 ,MIN(CASE WHEN ct.POD_STATUS = 'ECM380' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM380 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM390' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM390 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM420' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM420 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM510' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM510 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM520' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM520 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM530' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM530 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM540' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM540 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM550' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_ECM550 ,'N' AS MULTI_YN FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON odAdd.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_POD_03 p03 ON p03.OD_JOB_NO = od.OD_JOB_NO AND p03.BL_NO = od.HBL_NO LEFT JOIN TB_ECM_POD_04 p04 ON p04.OD_JOB_NO = od.OD_JOB_NO AND p04.BL_NO = od.HBL_NO LEFT JOIN TB_ECM_COUPANG_TRACKING ct ON ct.OD_JOB_NO = od.OD_JOB_NO AND ct.HBL_NO = od.HBL_NO WHERE od.MULTI_YN = 'N' AND od.OD_JOB_NO IN ( SELECT DISTINCT OD_JOB_NO FROM TB_ECM_POD_01 WHERE POD_STATUS >= 'ECM010' ) GROUP BY od.OD_JOB_NO, od.ENT_CODE, od.ENT_BUSINESS_CODE, od.BOUND, od.BOUND_TYPE, od.CUST_CODE_LV1, od.CUST_CODE_LV2, od.PO_NO, od.PO_DATE, od.AR_DATE, od.HBL_NO, od.DELIVERY_CODE, od.CD_TYPE, odAdd.DROP_YN, odAdd.RETURN_REQUEST_ID, odAdd.RETURN_REQ_DATE
UNION ALL
SELECT od.OD_JOB_NO ,MAX(od.MASTER_OD_JOB_NO) AS MASTER_OD_JOB_NO ,od.ENT_CODE ,od.ENT_BUSINESS_CODE ,od.BOUND ,od.BOUND_TYPE ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS CUST_NAME_LV2 ,od.PO_NO ,od.PO_DATE ,od.AR_DATE ,mt.DELIVERY_NO AS HBL_NO ,mt.DELIVERY_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = mt.DELIVERY_CODE) AS DELIVERY_NAME ,od.CD_TYPE ,odAdd.DROP_YN ,mt.RETURN_REQUEST_ID ,mt.RETURN_REQ_DATE ,MAX(CASE WHEN p03.POD_STATUS = 'ECM065' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_ID_ERROR ,MAX(CASE WHEN ct.POD_STATUS = 'ECM065' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_CUSTOMS_ID_ERROR ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM250' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN od.CD_TYPE = 'Y' AND p03.POD_STATUS = 'ECM210' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_START ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM280' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN od.CD_TYPE = 'Y' AND p03.POD_STATUS = 'ECM240' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_CLEAR ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND ct.POD_STATUS = 'ECM250' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN od.CD_TYPE = 'Y' AND ct.POD_STATUS = 'ECM210' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_CUSTOMS_START ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND ct.POD_STATUS = 'ECM280' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN od.CD_TYPE = 'Y' AND ct.POD_STATUS = 'ECM240' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) END) AS CT_CUSTOMS_CLEAR ,MAX(CASE WHEN p04.POD_STATUS = 'ECM361' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM361' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM361 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM370' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM370' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM370 ,MIN(CASE WHEN p04.POD_STATUS = 'ECM380' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM380' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM380 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM390' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM390' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM390 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM420' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM420' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM420 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM510' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM510' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM510 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM520' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM520' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM520 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM530' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM530' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM530 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM540' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM540' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM540 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM550' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM550' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM550 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM361' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM361' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM361 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM370' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM370' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM370 ,MIN(CASE WHEN ct.POD_STATUS = 'ECM380' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM380' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM380 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM390' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM390' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM390 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM420' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM420' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM420 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM510' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM510' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM510 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM520' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM520' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM520 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM530' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM530' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM530 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM540' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM540' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM540 ,MAX(CASE WHEN ct.POD_STATUS = 'ECM550' THEN CONVERT(VARCHAR(16), ct.SEND_DATE_TIME, 120) WHEN ctm.POD_STATUS = 'ECM550' THEN CONVERT(VARCHAR(16), ctm.SEND_DATE_TIME, 120) END) AS CT_ECM550 ,'Y' AS MULTI_YN FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_MULTI mt ON mt.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON odAdd.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_POD_03 p03 ON p03.OD_JOB_NO = od.OD_JOB_NO AND p03.BL_NO = mt.DELIVERY_NO LEFT JOIN TB_ECM_POD_04 p04 ON p04.OD_JOB_NO = od.OD_JOB_NO AND p04.BL_NO = od.HBL_NO LEFT JOIN TB_ECM_POD_04_M p04m ON p04m.OD_JOB_NO = od.OD_JOB_NO AND p04m.BL_NO = mt.DELIVERY_NO LEFT JOIN TB_ECM_COUPANG_TRACKING ct ON ct.OD_JOB_NO = od.OD_JOB_NO AND ct.HBL_NO = od.HBL_NO LEFT JOIN TB_ECM_COUPANG_TRACKING ctm ON ctm.OD_JOB_NO = od.OD_JOB_NO AND ctm.HBL_NO = mt.DELIVERY_NO WHERE od.MULTI_YN = 'Y' AND od.OD_JOB_NO IN ( SELECT DISTINCT OD_JOB_NO FROM TB_ECM_POD_01 WHERE POD_STATUS >= 'ECM010' ) GROUP BY od.OD_JOB_NO, od.ENT_CODE, od.ENT_BUSINESS_CODE, od.BOUND, od.BOUND_TYPE, od.CUST_CODE_LV1, od.CUST_CODE_LV2, od.PO_NO, od.PO_DATE, od.AR_DATE, mt.DELIVERY_NO, mt.DELIVERY_CODE, mt.RETURN_REQUEST_ID, mt.RETURN_REQ_DATE, od.CD_TYPE, odAdd.DROP_YN ) rst WHERE 1=1 AND rst.ENT_CODE = #{srchEntCode} AND rst.ENT_BUSINESS_CODE = #{srchEntBusinessCode} AND rst.CUST_CODE_LV1 = 'COUPANG-HQ'
AND rst.BOUND_TYPE = 'IMP'
AND rst.BOUND = 'AIR'
AND rst.BOUND = 'SEA'
AND rst.CUST_CODE_LV1 = #{srchCuslv1}
AND rst.CUST_CODE_LV2 = #{srchCuslv2}
AND rst.DELIVERY_CODE = #{srchDelivery}
AND rst.RETURN_REQ_DATE IS NOT NULL
AND rst.RETURN_REQ_DATE IS NULL
AND rst.RETURN_REQ_DATE IS NOT NULL
AND rst.RETURN_REQUEST_ID IS NOT NULL
AND rst.RETURN_REQUEST_ID IS NULL
AND (
rst.CUSTOMS_START IS NOT NULL rst.CUSTOMS_CLEAR IS NOT NULL rst.ECM361 IS NOT NULL rst.ECM370 IS NOT NULL rst.ECM380 IS NOT NULL rst.ECM390 IS NOT NULL rst.ECM420 IS NOT NULL rst.ECM510 IS NOT NULL rst.ECM550 IS NOT NULL rst.ECM520 IS NOT NULL rst.ECM530 IS NOT NULL rst.ECM540 IS NOT NULL
)
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND rst.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}

/* PodMapper.selectPodList : POD(공통) List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT * FROM ( SELECT od.OD_JOB_NO ,od.ENT_CODE ,od.ENT_BUSINESS_CODE ,od.BOUND ,od.BOUND_TYPE ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS CUST_NAME_LV2 ,od.PO_NO ,od.PO_DATE ,od.AR_DATE ,od.MBL_NO ,od.HBL_NO ,od.DELIVERY_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = od.DELIVERY_CODE) AS DELIVERY_NAME ,od.CD_TYPE ,od.PIECES ,od.GWT ,od.SHIPPER_NAME ,od.CONSIGNEE_NAME_LOC ,od.CONSIGNEE_HP ,odAdd.DROP_YN ,odAdd.RETURN_REQUEST_ID ,odAdd.RETURN_REQ_DATE ,MAX(CASE WHEN p01.POD_STATUS = 'ECM010' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM010 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM020' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM020 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM005' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM005 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM007' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM007 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM060' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM060 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM070' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM070 ,MAX(CASE WHEN p03.POD_STATUS = 'ECM210' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS ECM210 ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM250' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN (od.CD_TYPE = 'Y' AND odAdd.CARRYIN_DATE IS NOT NULL) AND p03.POD_STATUS = 'ECM210' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_START ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM280' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN od.CD_TYPE = 'Y' AND p03.POD_STATUS = 'ECM240' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_CLEAR ,MAX(CASE WHEN p03.POD_STATUS = 'ECM290' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS ECM290 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM360' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM360 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM400' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM400 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM420' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) END) AS ECM420 ,'N' AS MULTI_YN FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON odAdd.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_POD_01 p01 ON p01.OD_JOB_NO = od.OD_JOB_NO AND p01.BL_NO = od.HBL_NO LEFT JOIN TB_ECM_POD_03 p03 ON p03.OD_JOB_NO = od.OD_JOB_NO AND p03.BL_NO = od.HBL_NO LEFT JOIN TB_ECM_POD_04 p04 ON p04.OD_JOB_NO = od.OD_JOB_NO AND p04.BL_NO = od.HBL_NO WHERE od.MULTI_YN = 'N' AND od.OD_JOB_NO IN ( SELECT DISTINCT OD_JOB_NO FROM TB_ECM_POD_01 WHERE POD_STATUS >= 'ECM010' ) GROUP BY od.OD_JOB_NO, od.ENT_CODE, od.ENT_BUSINESS_CODE, od.BOUND, od.BOUND_TYPE, od.CUST_CODE_LV1, od.CUST_CODE_LV2, od.PO_NO, od.PO_DATE, od.AR_DATE, od.HBL_NO, od.MBL_NO, od.DELIVERY_CODE, od.CD_TYPE, od.PIECES, od.GWT, od.SHIPPER_NAME, od.CONSIGNEE_NAME_LOC, od.CONSIGNEE_HP, odAdd.DROP_YN, odAdd.RETURN_REQUEST_ID, odAdd.RETURN_REQ_DATE
UNION ALL
SELECT od.OD_JOB_NO ,od.ENT_CODE ,od.ENT_BUSINESS_CODE ,od.BOUND ,od.BOUND_TYPE ,od.CUST_CODE_LV1 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV1) AS CUST_NAME_LV1 ,od.CUST_CODE_LV2 ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV2) AS CUST_NAME_LV2 ,od.PO_NO ,od.PO_DATE ,od.AR_DATE ,od.MBL_NO ,mt.DELIVERY_NO AS HBL_NO ,mt.DELIVERY_CODE ,(SELECT NAME_KOR FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = od.ENT_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE' AND CODE = mt.DELIVERY_CODE) AS DELIVERY_NAME ,od.CD_TYPE ,od.PIECES ,od.GWT ,od.SHIPPER_NAME ,od.CONSIGNEE_NAME_LOC ,od.CONSIGNEE_HP ,odAdd.DROP_YN ,mt.RETURN_REQUEST_ID ,mt.RETURN_REQ_DATE ,MAX(CASE WHEN p01.POD_STATUS = 'ECM010' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM010 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM020' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM020 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM005' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM005 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM007' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM007 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM060' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM060 ,MAX(CASE WHEN p01.POD_STATUS = 'ECM070' THEN CONCAT(p01.POD_DATE, ' ', p01.POD_TIME) END) AS ECM070 ,MAX(CASE WHEN p03.POD_STATUS = 'ECM210' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS ECM210 ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM250' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN (od.CD_TYPE = 'Y' AND odAdd.CARRYIN_DATE IS NOT NULL) AND p03.POD_STATUS = 'ECM210' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_START ,MAX(CASE WHEN (od.CD_TYPE IN ('N', 'B') OR odAdd.DROP_YN = 'Y') AND p03.POD_STATUS = 'ECM280' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) WHEN od.CD_TYPE = 'Y' AND p03.POD_STATUS = 'ECM240' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS CUSTOMS_CLEAR ,MAX(CASE WHEN p03.POD_STATUS = 'ECM290' THEN CONCAT(p03.POD_DATE, ' ', p03.POD_TIME) END) AS ECM290 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM360' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM360' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM360 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM400' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM400' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM400 ,MAX(CASE WHEN p04.POD_STATUS = 'ECM420' THEN CONCAT(p04.POD_DATE, ' ', p04.POD_TIME) WHEN p04m.POD_STATUS = 'ECM420' THEN CONCAT(p04m.POD_DATE, ' ', p04m.POD_TIME) END) AS ECM420 ,'Y' AS MULTI_YN FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_MULTI mt ON mt.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_ADDITIONAL odAdd ON odAdd.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_POD_01 p01 ON p01.OD_JOB_NO = od.OD_JOB_NO AND p01.BL_NO = od.HBL_NO LEFT JOIN TB_ECM_POD_03 p03 ON p03.OD_JOB_NO = od.OD_JOB_NO AND p03.BL_NO = mt.DELIVERY_NO LEFT JOIN TB_ECM_POD_04 p04 ON p04.OD_JOB_NO = od.OD_JOB_NO AND p04.BL_NO = od.HBL_NO LEFT JOIN TB_ECM_POD_04_M p04m ON p04m.OD_JOB_NO = od.OD_JOB_NO AND p04m.BL_NO = mt.DELIVERY_NO WHERE od.MULTI_YN = 'Y' AND od.OD_JOB_NO IN ( SELECT DISTINCT OD_JOB_NO FROM TB_ECM_POD_01 WHERE POD_STATUS >= 'ECM010' ) GROUP BY od.OD_JOB_NO, od.ENT_CODE, od.ENT_BUSINESS_CODE, od.BOUND, od.BOUND_TYPE, od.CUST_CODE_LV1, od.CUST_CODE_LV2, od.PO_NO, od.PO_DATE, od.AR_DATE, od.MBL_NO, mt.DELIVERY_NO, mt.DELIVERY_CODE, mt.RETURN_REQUEST_ID, mt.RETURN_REQ_DATE, od.PIECES, od.GWT, od.SHIPPER_NAME, od.CONSIGNEE_NAME_LOC, od.CONSIGNEE_HP, od.CD_TYPE, odAdd.DROP_YN ) rst WHERE 1=1 AND rst.ENT_CODE = #{srchEntCode} AND rst.ENT_BUSINESS_CODE = #{srchEntBusinessCode} AND rst.CUST_CODE_LV1 != 'COUPANG-HQ'
AND rst.BOUND_TYPE = 'IMP'
AND rst.BOUND = 'AIR'
AND rst.BOUND = 'SEA'
AND rst.CUST_CODE_LV1 = #{srchCuslv1}
AND rst.CUST_CODE_LV2 = #{srchCuslv2}
AND rst.DELIVERY_CODE = #{srchDelivery}
AND rst.RETURN_REQ_DATE IS NOT NULL
AND rst.RETURN_REQ_DATE IS NULL
AND rst.RETURN_REQ_DATE IS NOT NULL
AND rst.RETURN_REQUEST_ID IS NOT NULL
AND rst.RETURN_REQUEST_ID IS NULL
AND (
rst.ECM010 IS NOT NULL rst.ECM020 IS NOT NULL rst.ECM005 IS NOT NULL rst.ECM007 IS NOT NULL rst.ECM060 IS NOT NULL rst.ECM070 IS NOT NULL rst.ECM210 IS NOT NULL rst.CUSTOMS_START IS NOT NULL rst.CUSTOMS_CLEAR IS NOT NULL rst.ECM290 IS NOT NULL rst.ECM360 IS NOT NULL rst.ECM400 IS NOT NULL rst.ECM420 IS NOT NULL
)
AND ${srchNoType} IN (#{item})
AND ${srchNoType} LIKE CONCAT(#{srchNo},'%')
AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND rst.CUST_CODE_LV${loginCustomerLev} = #{loginCustomerCd}
